SELECT CASE state WHEN 'Active' THEN 'active' WHEN 'Closed' THEN 'churned' WHEN 'Hold' THEN 'suspended' END AS "customer_status", AVG(FLOOR(ABS(CAST(credit_limit AS NUMBER(38, 6)) / CAST(5000 AS NUMBER(38, 6))) + 0.5) * SIGN(CAST(credit_limit AS NUMBER(38, 6)) / CAST(5000 AS NUMBER(38, 6))) * 5000) AS "credit_limit_r5000_avg" FROM accounts WHERE opened_at >= TO_TIMESTAMP('2026-08-25 15:00:00.000000', 'YYYY-MM-DD HH24:MI:SS.FF6') AND opened_at < TO_TIMESTAMP('2026-11-25 15:00:00.000000', 'YYYY-MM-DD HH24:MI:SS.FF6') GROUP BY CASE state WHEN 'Active' THEN 'active' WHEN 'Closed' THEN 'churned' WHEN 'Hold' THEN 'suspended' END FETCH FIRST 50 ROWS ONLY